using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Pmad.CodeCondenser.Core.Filtering;

/// <summary>
/// Detects auto-generated code at the file level (headers, filenames) and at the syntax tree level (attributes).
/// </summary>
public static class GeneratedCodeDetector
{
    private static readonly string[] GeneratedAttributeNames =
    [
        "GeneratedCode",
        "GeneratedCodeAttribute",
        "CompilerGenerated",
        "CompilerGeneratedAttribute"
    ];

    /// <summary>
    /// Checks whether a syntax node (such as a method, property, or token's parent) or any of its enclosing
    /// type declarations is decorated with [GeneratedCode] or [CompilerGenerated].
    /// </summary>
    public static bool HasGeneratedCodeAttribute(SyntaxNode? node)
    {
        if (node == null)
        {
            return false;
        }

        // 1. Check the node itself if it can have attributes
        if (HasGeneratedAttributeOnNode(node))
        {
            return true;
        }

        // 2. Check all enclosing member and type declarations (methods, properties, classes, structs, records, interfaces)
        var current = node.Parent;
        while (current != null)
        {
            if (current is MemberDeclarationSyntax member && HasGeneratedAttributeOnNode(member))
            {
                return true;
            }

            current = current.Parent;
        }

        return false;
    }

    /// <summary>
    /// Inspects the first 20 lines of a file on disk for standard &lt;auto-generated&gt; or &lt;autogenerated&gt; comment tags.
    /// </summary>
    public static bool HasAutoGeneratedHeader(string filePath)
    {
        if (string.IsNullOrWhiteSpace(filePath) || !File.Exists(filePath))
        {
            return false;
        }

        try
        {
            using var reader = new StreamReader(filePath);
            for (int i = 0; i < 20; i++)
            {
                var line = reader.ReadLine();
                if (line == null) break;

                if (line.Contains("<auto-generated", StringComparison.OrdinalIgnoreCase) ||
                    line.Contains("<autogenerated", StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }
        }
        catch
        {
            // Ignore I/O read errors during header check
        }

        return false;
    }

    /// <summary>
    /// Inspects the first 20 lines of in-memory text content for standard &lt;auto-generated&gt; or &lt;autogenerated&gt; comment tags.
    /// </summary>
    public static bool HasAutoGeneratedHeaderInContent(string content)
    {
        if (string.IsNullOrWhiteSpace(content))
        {
            return false;
        }

        using var reader = new StringReader(content);
        for (int i = 0; i < 20; i++)
        {
            var line = reader.ReadLine();
            if (line == null) break;

            if (line.Contains("<auto-generated", StringComparison.OrdinalIgnoreCase) ||
                line.Contains("<autogenerated", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasGeneratedAttributeOnNode(SyntaxNode node)
    {
        SyntaxList<AttributeListSyntax> attributeLists = node switch
        {
            MemberDeclarationSyntax member => member.AttributeLists,
            _ => default
        };

        foreach (var attributeList in attributeLists)
        {
            foreach (var attribute in attributeList.Attributes)
            {
                var attrName = attribute.Name.ToString();

                foreach (var pattern in GeneratedAttributeNames)
                {
                    if (attrName.Equals(pattern, StringComparison.OrdinalIgnoreCase) ||
                        attrName.EndsWith("." + pattern, StringComparison.OrdinalIgnoreCase))
                    {
                        return true;
                    }
                }
            }
        }

        return false;
    }
}
